const BODIES = (out) => ({"done_body": JSON.stringify({ status: 'done', result: out.outcome }), "log_body": JSON.stringify({ recipe: 'R10.2', item: String($('Config').first().json.body.job_ref), decision: out.outcome, rules: { message: $('Config').first().json.body.message_id, intent: out.label || null, reason: out.reason || null, slots: out.slots || [] } }), "failed_key_body": JSON.stringify({ status: 'failed', result: 'write failed' }), "failed_body": JSON.stringify({ recipe: 'R10.2', item: String($('Config').first().json.body.job_ref), reason: 'write failed', detail: 'Reply ' + $('Config').first().json.body.message_id + ': ' + out.action + ' write failed; the dispatcher phones the customer', owner: $('Config').first().json.dispatch_queue }), "task_body": JSON.stringify(out.task), "message_body": JSON.stringify(out.message)});
